"use strict";
const toggle=document.querySelector(".nav-toggle"),nav=document.querySelector("#page-nav");
toggle?.addEventListener("click",()=>{const open=toggle.getAttribute("aria-expanded")!=="true";toggle.setAttribute("aria-expanded",String(open));nav.classList.toggle("open",open);});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&nav?.classList.contains("open")){nav.classList.remove("open");toggle.setAttribute("aria-expanded","false");toggle.focus();}});
let filter="all";const search=document.querySelector("#product-search"),cards=[...document.querySelectorAll(".catalogue-card")],filters=[...document.querySelectorAll("[data-filter]")];
function updateProducts(){let count=0;cards.forEach(card=>{const show=(filter==="all"||card.dataset.category===filter)&&card.dataset.name.includes((search?.value||"").trim().toLowerCase());card.hidden=!show;if(show)count++;});document.querySelector("#product-count").textContent=count+" product"+(count===1?"":"s");document.querySelector("#no-products").hidden=count!==0;}
filters.forEach(button=>button.addEventListener("click",()=>{filter=button.dataset.filter;filters.forEach(b=>b.setAttribute("aria-pressed",String(b===button)));updateProducts();}));
search?.addEventListener("input",updateProducts);
const form=document.querySelector("#enquiry-form");if(form){const params=new URLSearchParams(location.search);if(params.get("region"))form.elements.region.value=params.get("region");if(params.get("request")==="partnership")form.elements.message.value="I would like to discuss a regional partnership opportunity for "+(params.get("region")||"my region")+". Please share the relevant business information.";
if([...form.elements.product.options].some(o=>o.value===params.get("product")))form.elements.product.value=params.get("product");if(params.get("request")==="leaflet")form.elements.message.value="Please send the current locally authorised product leaflet, available presentations and information for my market.";
form.addEventListener("submit",e=>{e.preventDefault();const d=new FormData(form);document.querySelector("#prepared-message").value="Product enquiry: "+d.get("product")+"\n\nName: "+d.get("name")+"\nEmail: "+d.get("email")+"\nOrganisation: "+d.get("organisation")+"\nCountry / region: "+d.get("region")+"\n\n"+d.get("message");document.querySelector("#enquiry-result").hidden=false;document.querySelector("#prepared-message").focus();});
document.querySelector("#copy-enquiry").addEventListener("click",async()=>{const field=document.querySelector("#prepared-message"),status=document.querySelector("#enquiry-status");try{await navigator.clipboard.writeText(field.value);status.textContent="Message copied. Share it through your existing company contact.";}catch{field.focus();field.select();status.textContent="Select and copy the prepared message using your device’s copy command.";}});
document.querySelector("#download-enquiry").addEventListener("click",()=>{const url=URL.createObjectURL(new Blob([document.querySelector("#prepared-message").value],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="product-enquiry.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}